async function ordinary(t){const s=await setup(t);s.edit(s.ids[0],'standard','Mine');s.edit(s.ids[1],'methodText','Other local field');await s.peer(s.ids[0],'standard','Base 1','Peer');await s.peer(s.ids[1],'reason','','Other peer field');await s.conflict();return s;}
for(const choice of ['mine','server'])void test('ordinary conflict '+choice+' continues the same Save after fresh comparison and commits once',async t=>{
 const s=await ordinary(t),node=s.host.querySelector('[data-ab-conflict]');assert.equal(s.posts().length,0,'read-only preflight finds conflict before dispatch');assert.match(node.querySelector('[data-ab-conflict-position]').textContent,/A:G.*A-CUT.*檢查標準/);for(const [id,value]of [['base','Base 1'],['mine','Mine'],['server','Peer']])assert.equal(node.querySelector('[data-ab-conflict-value="'+id+'"]').textContent,JSON.stringify(value));
 const revision=s.f.snapshot().row.revision;await s.click(choice);assert.equal(s.host.querySelector('[data-ab-conflict]'),null);assert.equal(s.posts().length,1);assert.equal(s.posts()[0].status,200);assert.equal(s.f.snapshot().row.revision,revision+1);assert.equal((await s.row(s.ids[0])).standard,choice==='mine'?'Mine':'Peer');assert.equal((await s.row(s.ids[1])).methodText,'Other local field');assert.equal((await s.row(s.ids[1])).reason,'Other peer field');assert.match(s.state().message,/已存取/);
});
void test('cancel/Close has zero requests and no RAM/base/receipt/DB changes; detached double click cannot choose later',async t=>{
 const s=await ordinary(t),oldMine=s.host.querySelector('[data-ab-conflict-choice="mine"]'),before=JSON.stringify(s.api.localSaveScopes()),base=JSON.stringify(s.state().localScopes.map(e=>e.base)),db=s.f.snapshot(),markers=[...s.memory],count=s.requests();
 const close=s.host.querySelector('[data-ab-conflict-close]');assert(close);close.click();close.click();oldMine.click();assert.equal(s.requests(),count);assert.equal(JSON.stringify(s.api.localSaveScopes()),before);assert.equal(JSON.stringify(s.state().localScopes.map(e=>e.base)),base);assert.deepEqual([...s.memory],markers);assert.deepEqual(s.f.snapshot(),db);assert.equal(s.state().conflict,null);
 await s.conflict();const newConflict=s.state().conflict;oldMine.click();assert.equal(s.state().conflict,newConflict,'old detached button cannot accept a new comparison');
});
void test('peer changes after choice authority read conservatively stop, then a new explicit Save compares fresh values',async t=>{
 const s=await ordinary(t),held=s.hold(r=>r.method==='GET'&&r.path==='/api/ipqc-ab');s.host.querySelector('[data-ab-conflict-choice="mine"]').click();const flight=s.state().intent.flight;await held.started;await s.peer(s.ids[0],'standard','Peer','New peer');const db=s.f.snapshot();held.release();await flight;assert.equal(s.posts().length,1);assert.equal(s.posts()[0].status,409);assert.deepEqual(s.f.snapshot(),db);assert.equal(s.state().intent,null);await s.conflict();assert.equal(s.posts().length,1);assert.equal(s.host.querySelector('[data-ab-conflict-value="base"]').textContent,'"Base 1"');assert.equal(s.host.querySelector('[data-ab-conflict-value="server"]').textContent,'"New peer"');
});
void test('double choice/Save clicks while continuation reads authority cannot reenter or add operations',async t=>{
 const s=await ordinary(t),button=s.host.querySelector('[data-ab-conflict-choice="mine"]'),held=s.hold(r=>r.method==='GET'&&r.path==='/api/ipqc-ab');button.click();const flight=s.state().intent.flight;button.click();await s.api.save();await held.started;held.release();await flight;assert.equal(s.posts().length,1);assert.equal(s.posts()[0].status,200);
});
void test('local delete versus peer edit remains soft-delete and mine preserves peer payload plus other rows',async t=>{
 const s=await setup(t);s.api.remove(s.ids[0]);s.edit(s.ids[1],'methodText','Keep local');await s.peer(s.ids[0],'standard','Base 1','Peer edits before delete');await s.conflict();assert.equal(s.host.querySelector('[data-ab-conflict]').dataset.abConflictKind,'delete-edited');const n=s.requests();await s.click('mine');assert(s.requests()>n,'choice explicitly continues Save');const row=await s.row(s.ids[0]);assert(row);assert.equal(row.deleted,true);assert.equal(row.standard,'Peer edits before delete');assert.equal((await s.row(s.ids[1])).methodText,'Keep local');
});
void test('theirs cancels only the local delete, retaining unrelated local modifications',async t=>{
 const s=await setup(t);s.api.remove(s.ids[0]);s.edit(s.ids[1],'methodText','Keep local');await s.peer(s.ids[0],'standard','Base 1','Peer');await s.conflict();await s.click('server');assert.equal((await s.row(s.ids[0])).deleted,false);assert.equal((await s.row(s.ids[0])).standard,'Peer');assert.equal((await s.row(s.ids[1])).methodText,'Keep local');
});
void test('peer soft-delete keeps a record: mine retains RAM without resurrection, theirs accepts tombstone',async t=>{
 const s=await setup(t);s.edit(s.ids[0],'standard','Private edit');s.edit(s.ids[1],'methodText','Keep local');await s.remove(s.ids[0]);const row=await s.row(s.ids[0]);assert(row?.deleted);await s.conflict();assert.equal(s.host.querySelector('[data-ab-conflict]').dataset.abConflictKind,'edit-deleted');assert.match(s.host.textContent,/還原權限/);const db=s.f.snapshot(),count=s.requests(),local=JSON.stringify(s.api.localSaveScopes());await s.click('mine');assert.equal(s.requests(),count);assert.equal(JSON.stringify(s.api.localSaveScopes()),local);assert.deepEqual(s.f.snapshot(),db);await s.click('server');assert(s.requests()>count);assert.equal((await s.row(s.ids[0])).deleted,true);assert.equal((await s.row(s.ids[1])).methodText,'Keep local');
});
void test('both normal deletes reconcile an existing tombstone without another delete command',async t=>{
 const s=await setup(t);s.api.remove(s.ids[0]);s.edit(s.ids[1],'reason','Keep');await s.remove(s.ids[0]);await s.conflict();assert.equal(s.host.querySelector('[data-ab-conflict]').dataset.abConflictKind,'already-deleted');await s.click('mine');const changes=s.posts().at(-1).body.command.input.scopes.flatMap(e=>e.changes);assert(changes.every(c=>!c.moduleAction?.startsWith('delete')));assert.equal((await s.row(s.ids[0])).deleted,true);assert.equal((await s.row(s.ids[1])).reason,'Keep');
});
for(const change of ['actor','epoch','delivery'])void test('stale '+change+' cannot accept or cancel an old private comparison',async t=>{
 const s=await ordinary(t),before=JSON.stringify(s.api.localSaveScopes()),count=s.requests(),conflict=s.state().conflict;s.owner(change);await s.click('mine');await s.click('cancel');assert.equal(s.requests(),count);assert.equal(JSON.stringify(s.api.localSaveScopes()),before);assert.equal(s.state().conflict,conflict);
});
