// New module-local adoption proof. All peer journal operations use the real
// isolated module handler and its ordinary actor/revision/guard/CAS boundaries.
async function peerColdModuleSave(s,{changes,expected=200}={}){
 const m=await s.f.read('ipqc-ab','ab-only','&module=1');if(!m.control.workflow)await s.f.begin('ipqc-ab','ab-only',200,'&module=1');
 const g=await s.f.read('ipqc-ab','ab-only','&scope=A%3AG');assert.equal(g.control.workflow,undefined);
 return s.f.command('ipqc-ab','save',{moduleAction:'save-local-v1',input:{scopes:[{scope:'A:G',generation:null,baseId:g.control.activeVersionId,changes:changes||[patch(s.ids[0],'standard','Base 1','Module peer'),patch(s.ids[1],'methodText','','Peer module-only')]}]}},'ab-only',expected,'&module=1');
}
