void test('module adoption later peer changes are dual-fenced with no post-dispatch chooser or automatic retry',async t=>{
 const s=await setup(t,{coldLegacy:true,coldDraftDifference:true});editColdThroughForm(s,s.ids[0],'Mine');await peerColdModuleSave(s);await s.conflict();const held=s.hold(r=>r.method==='GET'&&r.path==='/api/ipqc-ab');s.host.querySelector('[data-ab-conflict-choice="mine"]').click();const pending=s.state().intent.flight;try{await Promise.race([held.started,pending.then(()=>{throw Error('Expected continuation read');})]);await s.f.command('ipqc-ab','apply',patch(s.ids[0],'standard','Module peer','Later module peer'),'ab-only',200,'&scope=A%3AG');}finally{held.release();await pending;}assert.equal(savePosts(s).length,1);assert.equal(savePosts(s)[0].status,409);assert.equal(s.state().conflict,null);assert.equal((await s.row(s.ids[0])).standard,'Later module peer');await s.conflict();await s.click('server');assert.equal(savePosts(s).length,2);assert.equal(savePosts(s)[1].status,200);assert.equal(beginPosts(s).length,0);
});
void test('module adoption CAS retry cannot stamp its legacy initializer witness over a peer group Begin',async t=>{
 const s=await setup(t,{coldLegacy:true,coldDraftDifference:true});await s.f.begin('ipqc-ab','ab-only',200,'&module=1');const prepare=s.f.env.DB.prepare.bind(s.f.env.DB);let intercept=true;s.f.env.DB.prepare=sql=>{const statement=prepare(sql);if(/UPDATE shared_state SET/.test(sql)){const run=statement.run.bind(statement);statement.run=async()=>{if(intercept){intercept=false;await s.f.begin('ipqc-ab','editor',200,'&scope=A%3AG');return{meta:{changes:0}};}return run();};}return statement;};await peerColdModuleSave(s,{expected:409});const g=(await s.f.read('ipqc-ab','editor','&scope=A%3AG')).control;assert.equal(g.coldOrigin.kind,'ipqc-ab-cold-origin-v1');assert.equal(g.workflow.active.content.items[1].reason,'');assert.equal(g.workflow.working.items[1].reason,'Legacy unsaved difference');assert.equal(g.workflow.working.items[0].standard,'Base 1');assert.equal((await lineageRead(s)).localLineage.groups['A:G'].reason,null);
});
for(const changed of ['source','approved'])void test('module adoption does not excuse a genuinely changed '+changed+' lineage',async t=>{
 const s=await setup(t,{coldLegacy:true,coldDraftDifference:true});editColdThroughForm(s,s.ids[0],'Mine');await peerColdModuleSave(s);await changeColdRoot(s,root=>{if(changed==='source')root.source={fileName:'Different approved source',sha256:'different'};else root.scopes['A:G'].versions.find(v=>v.id==='legacy-active').snapshot={errors:[],items:[]};});const db=s.f.snapshot();await s.api.save();assert.equal(savePosts(s).length,0);assert.equal(beginPosts(s).length,0);assert.equal(s.state().localScopes[0].generation,null);assert.equal(s.state().localScopes[0].snapshot.items[0].standard,'Mine');assert.deepEqual(s.f.snapshot(),db);
});

