 await s.peer(s.ids[0],'standard','Base 1','A peer');await s.f.command('ipqc-ab','apply',patch(s.otherId,'standard','B base','B peer'),'editor',200,'&scope=B%3AH');await s.conflict();const labels=s.host.querySelector('[data-ab-conflict-locations]').textContent;assert.match(labels,/A:G/);assert.match(labels,/B:H/);assert.equal(s.host.querySelectorAll('[data-ab-conflict-entry]').length,2);const revision=s.f.snapshot().row.revision;await s.click(choice);
 assert.equal(s.posts().length,1);assert.equal(s.posts()[0].status,200);assert.equal(s.f.snapshot().row.revision,revision+1);assert.equal((await s.row(s.ids[0])).standard,'A '+(choice==='mine'?'mine':'peer'));const b=await s.f.read('ipqc-ab','editor','&scope=B%3AH');assert.equal(b.control.workflow.working.items[0].standard,'B '+(choice==='mine'?'mine':'peer'));
